from __future__ import annotations

from .web_admin_read_runtime import ADMIN_READ_SCRIPT

ADMIN_SCRIPT = (
    'function adminMetric(label,value){return `<div class="card"><div class="muted">${esc(label)}</div><div class="metric">${esc(value)}</div></div>`}\n'
    + ADMIN_READ_SCRIPT
    + 'function renderAdminUsers(rows){return rows.length?\'<table class="table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Plan</th><th>Nodes</th><th>Ops 30d</th><th>Last active</th></tr></thead><tbody>\'+rows.map(u=>`<tr style="cursor:pointer" onclick="showAdminUser(\'${u.id}\')"><td><b>${esc(u.email)}</b><div class="muted">${esc(u.name||\'\')}</div></td><td>${esc(u.role)}</td><td>${esc(u.status)}</td><td>${esc(u.plan)}</td><td>${esc(u.node_count)}</td><td>${esc(u.operations_30d)}</td><td>${esc(timefmt(u.last_login_at))}</td></tr>`).join(\'\')+\'</tbody></table>\':\'<div class="card empty">No users.</div>\'}\nfunction renderAdminOps(rows){return rows.length?\'<table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Target</th><th>Status</th></tr></thead><tbody>\'+rows.map(o=>`<tr><td>${esc(timefmt(o.created_at))}</td><td>${esc(o.email||\'—\')}</td><td>${esc(o.action)}</td><td>${esc(o.target||\'—\')}</td><td>${esc(o.status)}</td></tr>`).join(\'\')+\'</tbody></table>\':\'<div class="card empty">No operations.</div>\'}\nfunction adminExpiryValue(){const mode=adminDetailExpiry.value;if(mode===\'never\')return null;if(mode===\'7d\')return Date.now()/1000+7*86400;if(mode===\'30d\')return Date.now()/1000+30*86400;if(mode===\'custom\'){const v=adminDetailExpiryCustom.value;if(!v)throw new Error(\'Choose an expiration date\');return new Date(v).getTime()/1000}return null}\nfunction adminExpiryModeChange(){if(window.adminDetailExpiryCustom)adminDetailExpiryCustom.classList.toggle(\'hidden\',adminDetailExpiry.value!==\'custom\')}\nasync function saveAdminUser(id){const isCurrent=adminUserViewOwner(id);try{await api(\'/api/admin/users/\'+encodeURIComponent(id),{method:\'PUT\',body:JSON.stringify({status:adminDetailStatus.value,plan:adminDetailPlan.value,bonus_requests:+adminDetailBonus.value||0,bonus_nodes:+adminDetailBonusNodes.value||0,bonus_ai_accounts:+adminDetailBonusAi.value||0,override_expires_at:adminExpiryValue()})},isCurrent);if(!isCurrent())return;toast(\'User updated\');await refreshAdminUser(id,isCurrent)}catch(e){if(isCurrent())toast(e.message)}}\nif(WEB_LANG===\'zh\'){localizeWeb();new MutationObserver(mutations=>{for(const m of mutations){for(const n of m.addedNodes){if(n.nodeType===Node.ELEMENT_NODE)localizeWeb(n);else if(n.nodeType===Node.TEXT_NODE&&WEB_ZH[n.nodeValue.trim()])n.nodeValue=WEB_ZH[n.nodeValue.trim()]}}}).observe(document.body,{childList:true,subtree:true})}\ndocument.addEventListener(\'keydown\',e=>{if(e.key===\'Escape\'&&window.adminUserModal&&(!adminUserModal.classList.contains(\'hidden\')||adminSelectedUserId!==null))closeModal(\'adminUserModal\')});\nboot();\n</script>\n</body></html>'
)
